class Solution {
  public String sortVowels(String s) {
    int[] freq = new int[5], firstSeen = new int[5];
    java.util.Arrays.fill(firstSeen, Integer.MAX_VALUE);
    String vowels = "aeiou";
    for (int i = 0; i < s.length(); i++) {
      int v = vowels.indexOf(s.charAt(i));
      if (v < 0) continue;
      freq[v]++;
      firstSeen[v] = Math.min(firstSeen[v], i);
    }
    Integer[] order = {0, 1, 2, 3, 4};
    java.util.Arrays.sort(
        order,
        (a, b) ->
            freq[a] != freq[b]
                ? Integer.compare(freq[b], freq[a])
                : Integer.compare(firstSeen[a], firstSeen[b]));
    StringBuilder sorted = new StringBuilder();
    for (int v : order) for (int c = 0; c < freq[v]; c++) sorted.append(vowels.charAt(v));
    StringBuilder sb = new StringBuilder();
    int p = 0;
    for (int i = 0; i < s.length(); i++) {
      if (vowels.indexOf(s.charAt(i)) >= 0) sb.append(sorted.charAt(p++));
      else sb.append(s.charAt(i));
    }
    return sb.toString();
  }
}
